INSERT INTO home_detail (
    home_id, build_date, home_floor, building_total_floors,
    home_direction, bathroom_count, is_pet, is_parking_available
) VALUES (
             #{homeId}, #{buildDate}, #{homeFloor}, #{buildingTotalFloors},
             #{homeDirection}, #{bathroomCnt}, #{isPet}, #{isParking}
         )

mapper.select:
SELECT
h.home_id as homeId, h.user_id as userId, h.addr1, h.addr2,
h.residence_type as residenceType, h.lease_type as leaseType,
h.deposit_price as depositPrice, h.monthly_rent as monthlyRent,
h.maintenance_fee as maintenaceFee, h.home_status as homeStatus,
h.view_cnt as viewCnt, h.like_cnt as likeCnt, h.chat_cnt as chatCnt,
h.room_cnt as roomCnt, h.supply_area as supplyArea, h.exclusive_area as exclusiveArea,
h.created_at as createdAt, h.updated_at as updatedAt
FROM home h
WHERE 1=1

    AND h.residence_type = #{search.residenceType}


    AND h.lease_type = #{search.leaseType}


    AND h.home_status = #{search.homeStatus}


    AND h.deposit_price >= #{search.minDepositPrice}


    AND h.deposit_price <= #{search.maxDepositPrice}


    AND h.monthly_rent >= #{search.minMonthlyRent}


    AND h.monthly_rent <= #{search.maxMonthlyRent}


    AND h.maintenance_fee <= #{search.maxMaintenanceFee}


    AND h.supply_area >= #{search.minSupplyArea}


    AND h.supply_area <= #{search.maxSupplyArea}


    AND h.room_cnt >= #{search.minRoomCnt}


    AND h.room_cnt <= #{search.maxRoomCnt}


    AND h.addr1 LIKE CONCAT('%', #{search.addr1}, '%')

ORDER BY h.created_at DESC
LIMIT #{search.limit} OFFSET #{search.offset}

SELECT home_id, maintenance_id, fee
FROM home_maintenance_fee
WHERE home_id = #{homeId}

mapper.update:
UPDATE home
SET view_cnt = view_cnt + 1
WHERE home_id = #{homeId}

