SELECT COUNT(*)
FROM home h
WHERE 1=1

    AND h.residence_type = #{search.residenceType}


    AND h.lease_type = #{search.leaseType}


    AND h.home_status = #{search.homeStatus}


    AND h.deposit_price >= #{search.minDepositPrice}


    AND h.deposit_price <= #{search.maxDepositPrice}


    AND h.monthly_rent >= #{search.minMonthlyRent}


    AND h.monthly_rent <= #{search.maxMonthlyRent}


    AND h.maintenance_fee <= #{search.maxMaintenanceFee}


    AND h.supply_area >= #{search.minSupplyArea}


    AND h.supply_area <= #{search.maxSupplyArea}


    AND h.room_cnt >= #{search.minRoomCnt}


    AND h.room_cnt <= #{search.maxRoomCnt}


    AND h.addr1 LIKE CONCAT('%', #{search.addr1}, '%')

SELECT COUNT(*)
FROM home_like
WHERE user_id = #{userId} AND home_id = #{homeId}

